public struct CoreConnectionSecurity {
    public var hostKeyAlgorithm: String
    public var hostKeyFingerprint: String
    public var keyExchangeAlgorithm: String
    public var clientToServerCipher: String
    public var serverToClientCipher: String
    public var clientToServerMac: String?
    public var serverToClientMac: String?

    // Default memberwise initializers are never public by default, so we
    // declare one manually.
    public init(hostKeyAlgorithm: String, hostKeyFingerprint: String, keyExchangeAlgorithm: String, clientToServerCipher: String, serverToClientCipher: String, clientToServerMac: String?, serverToClientMac: String?) {
        self.hostKeyAlgorithm = hostKeyAlgorithm
        self.hostKeyFingerprint = hostKeyFingerprint
        self.keyExchangeAlgorithm = keyExchangeAlgorithm
        self.clientToServerCipher = clientToServerCipher
        self.serverToClientCipher = serverToClientCipher
        self.clientToServerMac = clientToServerMac
        self.serverToClientMac = serverToClientMac
    }
}

#if compiler(>=6)
extension CoreConnectionSecurity: Sendable {}
#endif


extension CoreConnectionSecurity: Equatable, Hashable {
    public static func ==(lhs: CoreConnectionSecurity, rhs: CoreConnectionSecurity) -> Bool {
        if lhs.hostKeyAlgorithm != rhs.hostKeyAlgorithm {
            return false
        }
        if lhs.hostKeyFingerprint != rhs.hostKeyFingerprint {
            return false
        }
        if lhs.keyExchangeAlgorithm != rhs.keyExchangeAlgorithm {
            return false
        }
        if lhs.clientToServerCipher != rhs.clientToServerCipher {
            return false
        }
        if lhs.serverToClientCipher != rhs.serverToClientCipher {
            return false
        }
        if lhs.clientToServerMac != rhs.clientToServerMac {
            return false
        }
        if lhs.serverToClientMac != rhs.serverToClientMac {
            return false
        }
        return true
    }

    public func hash(into hasher: inout Hasher) {
        hasher.combine(hostKeyAlgorithm)
        hasher.combine(hostKeyFingerprint)
        hasher.combine(keyExchangeAlgorithm)
        hasher.combine(clientToServerCipher)
        hasher.combine(serverToClientCipher)
        hasher.combine(clientToServerMac)
        hasher.combine(serverToClientMac)
    }
}



